// Package corpus holds SQL statements to test s4ql's SQL front end with: statements extracted from
// SQLite's own test scripts, documentation, and fuzz corpora, and a few of s4ql's own. It stores no
// expectations; whether and how each statement parses is for SQLite to say when a test runs.
//
// The files tcl.txt, doc.txt, and fuzz.txt are generated by internal/sql/corpus/update from the
// archives of SQLite that source.json pins, and own.txt is written by hand. README.md says where
// each comes from and how to regenerate them.
//
// Each file holds one statement per line, in the form of [Encode]. Empty lines and lines that start
// with # are comments.
package corpus

import (
	"embed"
	"errors"
	"fmt"
	"strings"
	"unicode"
	"unicode/utf8"
)

// Sources of the corpus, in the order in which [All] gives them.
var Sources = []string{"tcl", "doc", "fuzz", "own"}

//go:embed tcl.txt doc.txt fuzz.txt own.txt
var files embed.FS

// Entry of the corpus: a statement and the source it came from, one of [Sources].
type Entry struct {
	Source string
	SQL    string
}

// All entries of the corpus, source by source in the order of [Sources], and in the order of each
// file within a source. A statement that is in more than one file is given once, with the first
// source. It panics if a file is malformed, which a test of this package rules out.
func All() []Entry {
	var entries []Entry
	seen := map[string]bool{}
	for _, source := range Sources {
		sqls, err := Read(source)
		if err != nil {
			panic(err)
		}
		for _, sql := range sqls {
			if seen[sql] {
				continue
			}
			seen[sql] = true
			entries = append(entries, Entry{Source: source, SQL: sql})
		}
	}
	return entries
}

// Read the statements of one source, in the order of its file.
func Read(source string) ([]string, error) {
	b, err := files.ReadFile(source + ".txt")
	if err != nil {
		return nil, err
	}
	return Parse(string(b))
}

// Parse the lines of a corpus file into its statements.
func Parse(data string) ([]string, error) {
	var sqls []string
	for i, line := range strings.Split(data, "\n") {
		if line == "" || line[0] == '#' {
			continue
		}
		sql, err := Decode(line)
		if err != nil {
			return nil, fmt.Errorf("line %v: %w", i+1, err)
		}
		sqls = append(sqls, sql)
	}
	return sqls, nil
}

// Encode a statement as one line: printable characters stand for themselves, apart from the
// backslash, which is \\; a line feed is \n, a tab \t, a carriage return \r; and every other byte,
// such as a control character, a NUL, a byte that is not UTF-8, or a character that is not printable,
// such as a byte order mark or a no-break space, is \xHH for each byte. A # at the start of the line
// is \x23, so that the line is not a comment.
func Encode(sql string) string {
	var b strings.Builder
	for i := 0; i < len(sql); {
		r, n := utf8.DecodeRuneInString(sql[i:])
		switch {
		case r == '\\':
			b.WriteString(`\\`)
		case r == '\n':
			b.WriteString(`\n`)
		case r == '\t':
			b.WriteString(`\t`)
		case r == '\r':
			b.WriteString(`\r`)
		case r == '#' && i == 0:
			b.WriteString(`\x23`)
		case r == utf8.RuneError && n == 1, !unicode.IsPrint(r):
			for _, c := range []byte(sql[i : i+n]) {
				fmt.Fprintf(&b, `\x%02x`, c)
			}
		default:
			b.WriteString(sql[i : i+n])
		}
		i += n
	}
	return b.String()
}

// Decode a line in the form of [Encode] into its statement.
func Decode(line string) (string, error) {
	if strings.ContainsAny(line, "\n\r") {
		return "", errors.New("line break in a line")
	}
	var b strings.Builder
	for i := 0; i < len(line); i++ {
		c := line[i]
		if c != '\\' {
			b.WriteByte(c)
			continue
		}
		i++
		if i >= len(line) {
			return "", errors.New("backslash at the end of the line")
		}
		switch line[i] {
		case '\\':
			b.WriteByte('\\')
		case 'n':
			b.WriteByte('\n')
		case 't':
			b.WriteByte('\t')
		case 'r':
			b.WriteByte('\r')
		case 'x':
			if i+2 >= len(line) {
				return "", errors.New(`incomplete \x escape`)
			}
			hi, ok1 := unhex(line[i+1])
			lo, ok2 := unhex(line[i+2])
			if !ok1 || !ok2 {
				return "", fmt.Errorf(`bad \x escape %q`, line[i-1:i+3])
			}
			b.WriteByte(hi<<4 | lo)
			i += 2
		default:
			return "", fmt.Errorf(`unknown escape \%c`, line[i])
		}
	}
	if b.Len() == 0 {
		return "", errors.New("empty statement")
	}
	return b.String(), nil
}

func unhex(c byte) (byte, bool) {
	switch {
	case '0' <= c && c <= '9':
		return c - '0', true
	case 'a' <= c && c <= 'f':
		return c - 'a' + 10, true
	default:
		return 0, false
	}
}
